python3 -c "
unit='(((.(((((((...))))..))))))'
print('unit len',len(unit))
print(list(enumerate(unit,1)))
# pairing: stack opens
stack=[]
pairs={}
for i,c in enumerate(unit):
    if c=='(' : stack.append(i)
    elif c==')': j=stack.pop(); pairs[j]=i; pairs[i]=j
for i in range(len(unit)):
    if i in pairs and i<pairs[i]: print(i+1,'-',pairs[i]+1)
"
